import pytest

from banco_mvp import calcular_descuento


def test_descuento_normal():
    assert calcular_descuento(precio=100.0, porcentaje=20.0) == pytest.approx(80.0)

def test_sin_descuento():
    assert calcular_descuento(precio=50.0, porcentaje=0.0) == pytest.approx(50.0)

def test_precio_negativo():
    with pytest.raises(ValueError):
        calcular_descuento(precio=-1.0, porcentaje=10.0)

def test_porcentaje_mayor_a_100():
    with pytest.raises(ValueError):
        calcular_descuento(precio=100.0, porcentaje=150.0)

